gRF(){return"\u0411\u04b1\u043b \u0431\u0435\u043b\u0433\u0456 \u049b\u0430\u0440\u0441\u044b \u043a\u0435\u043b\u0435 \u0436\u0430\u0442\u049b\u0430\u043d \u043a\u04e9\u043b\u0456\u043a\u043a\u0435 \u0436\u043e\u043b \u049b\u04b1\u049b\u044b\u0493\u044b\u043d \u0431\u0435\u0440\u0435 \u043c\u0435?"},
gRE(){return"\u0416\u043e\u049b. \u0421\u0456\u0437\u0434\u0456\u04a3 \u0431\u0430\u0493\u044b\u0442\u0442\u0430 \u049b\u043e\u0437\u0493\u0430\u043b\u0430\u0442\u044b\u043d \u043a\u04e9\u043b\u0456\u043a \u0431\u0430\u0441\u044b\u043c\u0434\u044b\u049b\u049b\u0430 \u0438\u0435."},
gRU(){return"\u0411\u04b1\u043b \u0431\u0435\u043b\u0433\u0456 \u0442\u04b1\u0440\u0430\u049b\u0442\u044b \u0442\u0430\u043a\u0441\u0438\u043b\u0435\u0440\u0433\u0435 \u043a\u0456\u0440\u0443\u0433\u0435 \u0442\u044b\u0439\u044b\u043c \u0441\u0430\u043b\u0430 \u043c\u0430?"},
gRT(){return"\u0418\u04d9. \u0422\u0430\u043a\u0441\u0438 \u043c\u0435\u043d \u043a\u04e9\u043b\u0456\u043a\u0442\u0456 \u043e\u0440\u0442\u0430\u049b \u043f\u0430\u0439\u0434\u0430\u043b\u0430\u043d\u0443 \u0442\u044b\u0439\u044b\u043c\u0493\u0430 \u0441\u04d9\u0439\u043a\u0435\u0441 \u043a\u0435\u043b\u0443\u0456 \u043a\u0435\u0440\u0435\u043a. \u0415\u0440\u0435\u043a\u0448\u0435\u043b\u0456\u043a - \u043c\u0430\u0440\u0448\u0440\u0443\u0442\u0442\u044b\u049b \u0442\u0430\u0441\u044b\u043c\u0430\u043b\u0434\u0430\u0443."},
gRW(){return"\u0421\u0456\u0437 \u0431\u0435\u043b\u0433\u0456\u043d\u0456\u04a3 \u0430\u0440\u0442\u044b\u043d\u0434\u0430 \u0442\u04b1\u0440\u044b\u043f \u0436\u0430\u0442\u049b\u0430\u043d\u0434\u044b\u049b\u0442\u0430\u043d \u0493\u0430\u043d\u0430 \u043a\u0456\u0440\u0435 \u0430\u043b\u0430\u0441\u044b\u0437 \u0431\u0430?"},
gRV(){return"\u0416\u043e\u049b. \u0422\u04b1\u0440\u0493\u044b\u043d\u0434\u0430\u0440 \u04af\u0448\u0456\u043d \u0435\u0440\u0435\u043a\u0448\u0435\u043b\u0456\u043a \u0436\u043e\u049b. \u0411\u04b1\u043b \u0431\u0435\u043b\u0433\u0456\u043d\u0456 \xab\u0416\u043e\u043b \u049b\u043e\u0437\u0493\u0430\u043b\u044b\u0441\u044b\u043d\u0430 \u0442\u044b\u0439\u044b\u043c \u0441\u0430\u043b\u044b\u043d\u0430\u0434\u044b\xbb \u0431\u0435\u043b\u0433\u0456\u0441\u0456\u043c\u0435\u043d \u0448\u0430\u0442\u0430\u0441\u0442\u044b\u0440\u043c\u0430\u04a3\u044b\u0437."},
gRY(){return"\u041c\u0430\u0440\u0448\u0440\u0443\u0442\u0442\u044b\u049b \u0430\u0432\u0442\u043e\u0431\u0443\u0441 \u04e9\u0437 \u0431\u0430\u0493\u044b\u0442\u044b\u043d\u0430 \u043a\u0456\u0440\u0435 \u0430\u043b\u0430 \u043c\u0430?"},
gRX(){return"\u0418\u04d9. \u0411\u04b1\u043b \u0431\u0435\u043b\u0433\u0456\u0433\u0435 \u0442\u044b\u0439\u044b\u043c \u0441\u0430\u043b\u0443 \u043c\u0430\u0440\u0448\u0440\u0443\u0442\u0442\u044b\u049b \u043a\u04e9\u043b\u0456\u043a\u0442\u0435\u0440\u0433\u0435 \u049b\u043e\u043b\u0434\u0430\u043d\u044b\u043b\u043c\u0430\u0439\u0434\u044b."},
