ga3Q(){return"\u0410\u043b\u0434\u0430\u0493\u044b \u0436\u043e\u043b\u0434\u044b \u043a\u04e9\u0440\u0443 \u04af\u0448\u0456\u043d \u0436\u0435\u0442\u043a\u0456\u043b\u0456\u043a\u0442\u0456 \u0430\u0440\u0430\u043b\u044b\u049b \u049b\u0430\u043b\u0434\u044b\u0440\u044b\u04a3\u044b\u0437. \u0416\u043e\u043b \u043a\u04e9\u0440\u0456\u043d\u0431\u0435\u0441\u0435, \u0431\u0430\u0441\u044b\u043f \u043e\u0437\u0443\u0434\u044b \u0431\u0430\u0441\u0442\u0430\u043c\u0430\u04a3\u044b\u0437."},
