ga3i(){return"\u0411\u04b1\u0440\u044b\u043b\u044b\u0441\u049b\u0430 \u0434\u0435\u0439\u0456\u043d \u0442\u04af\u0437\u0443 \u0436\u043e\u043b\u0434\u0430 \u0436\u044b\u043b\u0434\u0430\u043c\u0434\u044b\u049b\u0442\u044b \u0430\u0437\u0430\u0439\u0442\u044b\u04a3\u044b\u0437. \u0422\u0430\u0439\u0493\u0430\u049b \u0436\u043e\u043b\u0434\u0430 \u043a\u04af\u0440\u0442 \u04d9\u0440\u0435\u043a\u0435\u0442\u0441\u0456\u0437 \u0431\u04b1\u0440\u044b\u043b\u044b\u04a3\u044b\u0437."},
ga3l(){return"\u0411\u04b1\u0440\u044b\u043b\u044b\u0441\u0442\u044b \u043a\u04af\u0442\u043a\u0435\u043d\u0434\u0435 \u0434\u04e9\u04a3\u0433\u0435\u043b\u0435\u043a\u0442\u0456 \u0442\u04af\u0437\u0443 \u04b1\u0441\u0442\u0430\u04a3\u044b\u0437"},
ga3k(){return"\u0421\u043e\u043b\u0493\u0430 \u0431\u04b1\u0440\u044b\u043b\u0443\u0434\u044b \u043a\u04af\u0442\u043a\u0435\u043d\u0434\u0435 \u0434\u04e9\u04a3\u0433\u0435\u043b\u0435\u043a\u0442\u0456 \u0442\u04af\u0437\u0443 \u04b1\u0441\u0442\u0430\u04a3\u044b\u0437: \u0430\u0440\u0442\u0442\u0430\u043d \u0441\u043e\u049b\u049b\u044b \u0431\u043e\u043b\u0441\u0430, \u049b\u0430\u0440\u0441\u044b \u0436\u043e\u043b\u0430\u049b\u049b\u0430 \u0448\u044b\u0493\u0443 \u049b\u0430\u0443\u043f\u0456 \u0430\u0437\u0430\u044f\u0434\u044b."},
ga3n(){return"\u0416\u04af\u043a \u043a\u04e9\u043b\u0456\u0433\u0456\u043d\u0456\u04a3 \u0441\u043e\u049b\u044b\u0440 \u0430\u0439\u043c\u0430\u0493\u044b\u043d\u0434\u0430 \u049b\u0430\u043b\u043c\u0430\u04a3\u044b\u0437"},
ga3m(){return"\u041a\u0430\u0431\u0438\u043d\u0430 \u0436\u0430\u043d\u044b\u043d\u0434\u0430 \u043d\u0435\u043c\u0435\u0441\u0435 \u0442\u0456\u0440\u043a\u0435\u043c\u0435\u043d\u0456\u04a3 \u0434\u04d9\u043b \u0430\u0440\u0442\u044b\u043d\u0434\u0430 \u0436\u04af\u0440\u043c\u0435\u04a3\u0456\u0437: \u0436\u04af\u043a \u043a\u04e9\u043b\u0456\u0433\u0456\u043d\u0456\u04a3 \u0436\u04af\u0440\u0433\u0456\u0437\u0443\u0448\u0456\u0441\u0456 \u0441\u0456\u0437\u0434\u0456 \u043a\u04e9\u0440\u043c\u0435\u0443\u0456 \u043c\u04af\u043c\u043a\u0456\u043d."},
ga3p(){return"\u04e8\u0442\u043a\u0435\u043b\u0434\u0435 \u043a\u04e9\u0440\u0448\u0456 \u043a\u04e9\u043b\u0456\u043a \u0442\u0435\u0436\u0435\u0441\u0435, \u0441\u0456\u0437 \u0434\u0435 \u0442\u0435\u0436\u0435\u04a3\u0456\u0437"},
ga3o(){return"\u0421\u0456\u0437 \u0434\u0435 \u0436\u044b\u043b\u0434\u0430\u043c\u0434\u044b\u049b\u0442\u044b \u0430\u0437\u0430\u0439\u0442\u044b\u04a3\u044b\u0437 \u043d\u0435\u043c\u0435\u0441\u0435 \u0442\u043e\u049b\u0442\u0430\u04a3\u044b\u0437. \u0416\u0430\u044f\u0443 \u0436\u04af\u0440\u0433\u0456\u043d\u0448\u0456\u043b\u0435\u0440\u0433\u0435 \u0436\u043e\u043b \u0431\u0435\u0440\u0433\u0435\u043d \u0441\u043e\u04a3 \u0493\u0430\u043d\u0430 \u0436\u04af\u0440\u0456\u04a3\u0456\u0437."},
ga3r(){return"\u0411\u04b1\u0440\u044b\u043b\u044b\u043f \u0436\u0430\u0442\u049b\u0430\u043d \u0436\u04af\u043a \u043a\u04e9\u043b\u0456\u0433\u0456\u043d \u043e\u04a3\u043d\u0430\u043d \u0430\u0439\u043d\u0430\u043b\u043c\u0430\u04a3\u044b\u0437"},
ga3q(){return"\u041e\u04a3\u0493\u0430 \u0431\u04b1\u0440\u044b\u043b\u0493\u0430\u043d\u0434\u0430 \u0442\u0456\u0440\u043a\u0435\u043c\u0435 \u0456\u0448\u043a\u0456 \u0436\u0430\u049b\u049b\u0430 \u044b\u0493\u044b\u0441\u0430\u0434\u044b. \u0416\u04af\u043a \u043a\u04e9\u043b\u0456\u0433\u0456 \u043c\u0435\u043d \u0436\u0438\u0435\u043a\u0442\u0430\u0441 \u0430\u0440\u0430\u0441\u044b\u043d\u0434\u0430\u0493\u044b \u0441\u0430\u04a3\u044b\u043b\u0430\u0443\u0493\u0430 \u043a\u0456\u0440\u043c\u0435\u04a3\u0456\u0437."},
