gRr(){return"\u0414\u043e\u0440\u043e\u0433\u0430 \u0441\u0432\u043e\u0431\u043e\u0434\u043d\u0430. \u041f\u0435\u0440\u0435\u0434 \u044d\u0442\u0438\u043c \u0437\u043d\u0430\u043a\u043e\u043c \u0432\u0441\u0451 \u0440\u0430\u0432\u043d\u043e \u043d\u0443\u0436\u043d\u043e \u043e\u0441\u0442\u0430\u043d\u043e\u0432\u0438\u0442\u044c\u0441\u044f?"},
gRq(){return"\u041d\u0435\u0442. \u041e\u0431\u044f\u0437\u0430\u0442\u0435\u043b\u044c\u043d\u043e\u0439 \u043e\u0441\u0442\u0430\u043d\u043e\u0432\u043a\u0438 \u043d\u0435\u0442, \u0435\u0441\u043b\u0438 \u0432\u044b \u043d\u0438\u043a\u043e\u043c\u0443 \u043d\u0435 \u043c\u0435\u0448\u0430\u0435\u0442\u0435."},
